import{_ as a,o as e,c as n,a6 as d}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"QPACK 头部压缩","description":"HPACK 为何在乱序交付下失效、编码器/解码器流、Required Insert Count 与阻塞流。","frontmatter":{"title":"QPACK 头部压缩","description":"HPACK 为何在乱序交付下失效、编码器/解码器流、Required Insert Count 与阻塞流。","source":"https://daiw.org/manual/http2-3/qpack"},"headers":[],"relativePath":"manual/computer-programming/http2-3/qpack.md","filePath":"manual/computer-programming/http2-3/qpack.md"}'),r={name:"manual/computer-programming/http2-3/qpack.md"};function s(o,t,p,c,i,l){return e(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="qpack-头部压缩" tabindex="-1">QPACK 头部压缩 <a class="header-anchor" href="#qpack-头部压缩" aria-label="Permalink to &quot;QPACK 头部压缩&quot;">​</a></h1><p>HPACK 为何在乱序交付下失效、编码器/解码器流、Required Insert Count 与阻塞流。</p><p>RFC 9204。它存在的唯一原因：<strong>HPACK 在乱序交付的传输上会失效</strong>。</p><h2 id="hpack-为什么不能直接用" tabindex="-1">HPACK 为什么不能直接用 <a class="header-anchor" href="#hpack-为什么不能直接用" aria-label="Permalink to &quot;HPACK 为什么不能直接用&quot;">​</a></h2><p><a href="/Front2Full/manual/computer-programming/http2-3/hpack">HPACK 的动态表</a>要求编解码双方<strong>严格按同一顺序</strong>演进：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h2 (TCP，全局有序):</span></span>
<span class="line"><span>  请求1: 插入 &quot;cookie: abc&quot; → 动态表索引 62</span></span>
<span class="line"><span>  请求2: 引用索引 62</span></span>
<span class="line"><span>  → TCP 保证请求 1 先于请求 2 到达，解码必定成功</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>QUIC 的流是<strong>独立交付</strong>的——这正是它消除队头阻塞的方式，但也意味着<strong>没有全局顺序</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>h3 (QUIC，流间无序):</span></span>
<span class="line"><span>  流A: 插入 &quot;cookie: abc&quot; → 索引 62</span></span>
<span class="line"><span>  流B: 引用索引 62</span></span>
<span class="line"><span>  → 若流 A 的包丢失，流 B 先到达</span></span>
<span class="line"><span>  → 解码器不知道索引 62 是什么 → 解码失败</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>若为此强制全局有序，就等于把队头阻塞又装了回来——HTTP/3 的意义荡然无存。</p><p>QPACK 的解法：<strong>把「动态表更新」与「字段块引用」分离到不同的流上，并让编码器自己决定冒多大的阻塞风险。</strong></p><h2 id="三条流" tabindex="-1">三条流 <a class="header-anchor" href="#三条流" aria-label="Permalink to &quot;三条流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>流</th><th>方向</th><th>内容</th></tr></thead><tbody><tr><td><strong>请求流</strong></td><td>双向</td><td><code>HEADERS</code> 帧，含字段块（<strong>引用</strong>表项）</td></tr><tr><td><strong>编码器流</strong></td><td>单向</td><td>动态表<strong>插入</strong>指令</td></tr><tr><td><strong>解码器流</strong></td><td>单向</td><td>插入计数确认、流取消</td></tr></tbody></table><p>编码器把「插入 <code>cookie: abc</code>」发在<strong>编码器流</strong>上，把「引用它」发在<strong>请求流</strong>上。两条流独立交付。</p><h2 id="静态表" tabindex="-1">静态表 <a class="header-anchor" href="#静态表" aria-label="Permalink to &quot;静态表&quot;">​</a></h2><p>99 个条目（索引 0–98），比 HPACK 的 61 个更大，且是按 HTTP/3 实测流量重新统计选出的。节选：</p><table tabindex="0"><thead><tr><th>索引</th><th>字段名</th><th>值</th></tr></thead><tbody><tr><td>0</td><td><code>:authority</code></td><td>—</td></tr><tr><td>1</td><td><code>:path</code></td><td><code>/</code></td></tr><tr><td>17</td><td><code>:method</code></td><td><code>GET</code></td></tr><tr><td>25</td><td><code>:status</code></td><td><code>200</code></td></tr><tr><td>31</td><td><code>content-type</code></td><td><code>application/json</code></td></tr><tr><td>95</td><td><code>user-agent</code></td><td>—</td></tr></tbody></table><p>静态表<strong>无状态</strong>，任何流随时可引用，永不阻塞。</p><h2 id="动态表与绝对索引" tabindex="-1">动态表与绝对索引 <a class="header-anchor" href="#动态表与绝对索引" aria-label="Permalink to &quot;动态表与绝对索引&quot;">​</a></h2><p>QPACK 的动态表条目有<strong>绝对索引</strong>（从 0 起单调递增，永不回绕）。字段块中用两种相对形式引用：</p><ul><li><strong>相对索引</strong>：相对于该字段块的 <code>Base</code>。</li><li><strong>后基索引（post-base）</strong>：引用在本字段块编码<strong>之后</strong>才插入的条目。</li></ul><p>这套设计让编码器可以在同一往返中「边插入边引用」。</p><h2 id="required-insert-count" tabindex="-1">Required Insert Count <a class="header-anchor" href="#required-insert-count" aria-label="Permalink to &quot;Required Insert Count&quot;">​</a></h2><p>每个字段块的前缀里带 <strong>Required Insert Count（RIC）</strong>——解码本块所需的<strong>最小动态表插入数</strong>。</p><p>解码器的逻辑：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>若 已收到的插入数 &gt;= RIC:</span></span>
<span class="line"><span>    立即解码</span></span>
<span class="line"><span>否则:</span></span>
<span class="line"><span>    该流「阻塞」，等编码器流补齐后再解</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>RIC = 0 表示该块完全不引用动态表</strong>（只用静态表和字面量），可<strong>无条件立即解码</strong>——永不阻塞。</p><h2 id="阻塞流与风险控制" tabindex="-1">阻塞流与风险控制 <a class="header-anchor" href="#阻塞流与风险控制" aria-label="Permalink to &quot;阻塞流与风险控制&quot;">​</a></h2><p><code>SETTINGS_QPACK_BLOCKED_STREAMS</code>（默认 <strong>0</strong>）声明解码器<strong>最多容忍多少条流处于阻塞状态</strong>。</p><p>编码器据此权衡：</p><table tabindex="0"><thead><tr><th>编码器策略</th><th>压缩率</th><th>阻塞风险</th></tr></thead><tbody><tr><td>只用静态表 + 字面量（RIC 恒 0）</td><td>低</td><td><strong>零</strong></td></tr><tr><td>积极引用最新插入的条目</td><td>高</td><td>高——丢包时多条流一起等</td></tr><tr><td>只引用<strong>已被确认</strong>的条目</td><td>中</td><td><strong>零</strong>（确认意味着解码器已收到）</td></tr></tbody></table><p>第三种是生产中的常见折中：编码器通过<strong>解码器流</strong>上的 <code>Section Acknowledgement</code> 得知哪些插入已确认，只引用这些，从而在拿到大部分压缩收益的同时<strong>完全避免</strong>队头阻塞。</p><p>注意默认值：<code>QPACK_MAX_TABLE_CAPACITY</code> 与 <code>QPACK_BLOCKED_STREAMS</code> <strong>都默认为 0</strong>——即<strong>默认不启用动态表</strong>，退化为「静态表 + 字面量 + Huffman」。要用动态表必须双方显式协商。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><h3 id="编码器流指令" tabindex="-1">编码器流指令 <a class="header-anchor" href="#编码器流指令" aria-label="Permalink to &quot;编码器流指令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>首位模式</th><th>作用</th></tr></thead><tbody><tr><td>Set Dynamic Table Capacity</td><td><code>001xxxxx</code></td><td>调整动态表容量</td></tr><tr><td>Insert With Name Reference</td><td><code>1Txxxxxx</code></td><td>插入，名字引用静态/动态表</td></tr><tr><td>Insert With Literal Name</td><td><code>01Mxxxxx</code></td><td>插入，名字为字面量</td></tr><tr><td>Duplicate</td><td><code>000xxxxx</code></td><td>复制已有条目（把老条目挪到表头防淘汰）</td></tr></tbody></table><h3 id="解码器流指令" tabindex="-1">解码器流指令 <a class="header-anchor" href="#解码器流指令" aria-label="Permalink to &quot;解码器流指令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>首位模式</th><th>作用</th></tr></thead><tbody><tr><td>Section Acknowledgement</td><td><code>1xxxxxxx</code></td><td>确认某流的字段块已解码</td></tr><tr><td>Stream Cancellation</td><td><code>01xxxxxx</code></td><td>流被取消，其引用作废</td></tr><tr><td>Insert Count Increment</td><td><code>00xxxxxx</code></td><td>告知已处理的插入数</td></tr></tbody></table><p><code>Section Acknowledgement</code> 是关键的反馈通道：它让编码器知道「这个条目对端确实有了」，从而安全地重复引用。</p><h2 id="与-hpack-的对照" tabindex="-1">与 HPACK 的对照 <a class="header-anchor" href="#与-hpack-的对照" aria-label="Permalink to &quot;与 HPACK 的对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>HPACK (h2)</th><th>QPACK (h3)</th></tr></thead><tbody><tr><td>静态表</td><td>61 项</td><td><strong>99 项</strong></td></tr><tr><td>表更新与引用</td><td><strong>同一通道</strong>（严格有序）</td><td><strong>分离到不同流</strong></td></tr><tr><td>乱序容忍</td><td>无（必须有序）</td><td><strong>有</strong>（RIC + 阻塞机制）</td></tr><tr><td>表失步后果</td><td><code>COMPRESSION_ERROR</code> 杀连接</td><td><code>QPACK_DECOMPRESSION_FAILED</code> 杀连接</td></tr><tr><td>默认启用动态表</td><td>是（4096 字节）</td><td><strong>否</strong>（容量默认 0）</td></tr><tr><td>整数/字符串编码</td><td>前缀整数 + Huffman</td><td><strong>相同</strong>（复用 HPACK 的编码原语与 Huffman 表）</td></tr><tr><td>安全表示</td><td>Never Indexed</td><td>同样有（<code>N</code> 位）</td></tr></tbody></table><p><strong>编码原语是一样的</strong>——变的只是「如何在无序传输上安全地维护共享状态」这一层。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h3-connection">连接与服务发现</a>。</p>`,42)])])}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
